def prod_signs(arr):
    if not arr:
        return None

    magnitude_sum = sum(abs(x) for x in arr)
    product_sign = 1

    for x in arr:
        if x > 0:
            product_sign *= 1
        elif x < 0:
            product_sign *= -1
        else:
            product_sign = 0
            break

    return magnitude_sum * product_sign

